// Brief form answers -> the run: id, brief fields, dry-run switch, link or upload.
const item = $input.first();
const f = item.json;
const run_id = String($execution.id);
if (!/^[A-Za-z0-9_-]{1,64}$/.test(run_id)) throw new Error('execution id ' + run_id + ' is not a valid run id');
const txt = (k) => String(f[k] == null ? '' : f[k]).trim();
const brief = {
  brand: txt('Brand'), product: txt('Product'), audience: txt('Audience'), offer: txt('Offer'),
  key_messages: [txt('Key message 1'), txt('Key message 2'), txt('Key message 3')].filter(Boolean),
  disclaimer: txt('Required disclaimer'), look: txt('Look'), beats: String(f['Beats'] == null ? '' : f['Beats']),
};
for (const k of ['brand', 'product', 'offer']) if (!brief[k]) throw new Error('the brief needs a ' + k);
if (brief.key_messages.length < 3) throw new Error('the brief needs 3 key messages');
if (!brief.beats.trim()) throw new Error('the brief needs beats');
const link = txt('Source clip link');
if (link && !/^https:\/\/\S+$/i.test(link)) throw new Error('Source clip link must be an https:// address (no spaces)');
const bin = item.binary || {};
const key = Object.keys(bin)[0];
if (!link && !key) throw new Error('give a source clip: upload a file or paste an https link');
// the dry-run checkbox arrives as a JSON array: [] (unticked) means a live run; a missing field means dry (safe default)
const dr = f['Dry run'];
const dry_run = Array.isArray(dr) ? dr.length > 0 : true;
return [{ json: { run_id, brief, dry_run, link, source_origin: link ? 'link' : 'upload' }, binary: link ? {} : { data: bin[key] } }];

// /run answered with just the folder name: put the run and the uploaded file back.
const prev = $('Run: ids and brief').first();
return [{ json: prev.json, binary: prev.binary }];

// The end card shows the rulebook's disclaimer, so the brief's must be that text (case, spacing and punctuation ignored).
const prev = $('Run: restore').first();
const S = prev.json;
const rb = $input.first().json;
const norm = (s) => String(s).toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
if (norm(S.brief.disclaimer) !== norm(rb.disclaimer)) throw new Error("the brief's disclaimer differs from the approved one in the rulebook");
return [{ json: { ...S, rulebook: rb, disclaimer: rb.disclaimer }, binary: prev.binary }];

// The link's download is capped (single constant): refuse before anything is written into the run.
const MAX_MB = 95;
const b = $input.first().binary && $input.first().binary.data;
if (!b) throw new Error('the link gave no file');
const bytes = Number(b.bytes || 0);
if (bytes > MAX_MB * 1024 * 1024) throw new Error('the linked file is ' + Math.round(bytes / 1048576) + ' MB; the limit is ' + MAX_MB + ' MB');
return $input.all();

// One beat per line:  NAME START-END ROLE [POSITION ...]   (blank lines and # comments are ignored)
//   NAME      S1 .. S6, each once
//   START-END seconds in the source clip, e.g. 0.5-6.0
//   ROLE      a free label: opener-H1, tension, routine, opener-H2, calm, close
//   POSITION  where the 9:16 / 1:1 crop window sits, any of these (default: centre):
//             left | centre | right | auto | a number 0..1 (window centre as a share of the width)   -> the service's `face`
//             x9=0.21 and/or x1=0.30, comma-joined or separate (9:16 and 1:1 centres)              -> the service's `x`
const S = $input.first().json;
const FACES = { left: 'left', centre: 'centre', center: 'centre', right: 'right', auto: 'auto' };
const NAMES = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6'];
const text = S.brief.beats.replace(/(\d)\s*[-–—]\s*(\d)/g, '$1-$2');
const lines = text.split(/\r?\n/).map((l) => l.replace(/#.*$/, '').trim()).filter(Boolean);
const beats = [];
const errs = [];
lines.forEach((line, i) => {
  const where = 'beats line ' + (i + 1) + ' ("' + line + '")';
  const t = line.split(/\s+/);
  if (t.length < 3) { errs.push(where + ': needs NAME START-END ROLE'); return; }
  const name = t[0].toUpperCase();
  if (!NAMES.includes(name)) errs.push(where + ': the name must be one of ' + NAMES.join(', '));
  const m = t[1].match(/^(\d+(?:\.\d+)?)-(\d+(?:\.\d+)?)$/);
  if (!m) { errs.push(where + ': the times must look like 0.5-6.0'); return; }
  const start = Number(m[1]); const end = Number(m[2]);
  if (!(end > start)) errs.push(where + ': the end must be after the start');
  const beat = { name, start, end, role: t[2] };
  let face = 'centre'; const x = {};
  for (const tok of t.slice(3)) {
    const lower = tok.toLowerCase();
    if (FACES[lower]) { face = FACES[lower]; continue; }
    if (/^(0(\.\d+)?|1(\.0+)?|\.\d+)$/.test(lower)) { face = Number(lower); continue; }
    let ok = true;
    for (const part of lower.split(',').filter(Boolean)) {
      const p = part.match(/^(x9|x1|9x16|1x1)=(0(?:\.\d+)?|1(?:\.0+)?|\.\d+)$/);
      if (!p) { ok = false; break; }
      x[p[1] === 'x9' || p[1] === '9x16' ? '9X16' : '1X1'] = Number(p[2]);
    }
    if (!ok) errs.push(where + ': "' + tok + '" is not a position (left, centre, right, auto, 0..1, x9=0.2, x1=0.4)');
  }
  beat.face = face;
  if (Object.keys(x).length) beat.x = x;
  beats.push(beat);
});
const seen = beats.map((b) => b.name);
for (const n of NAMES) if (seen.filter((s) => s === n).length !== 1) errs.push('beat ' + n + ' must appear exactly once (all of S1 to S6 are needed)');
if (errs.length) throw new Error('beats: ' + errs.join('; '));
beats.sort((a, b) => a.name.localeCompare(b.name));
const body = { run_id: S.run_id, source: S.source, beats, formats: ['9X16', '1X1'] };
return [{ json: { ...S, beats, body } }];

const S = $('Beats: parse').first().json;
